for name,encoded in IMAGES.items():
 path=Path(name);path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(base64.b64decode(encoded))
p=Path('index.html');text=p.read_text()
fixes={'"My Choice" Leaked':'assets/era-covers/love-everyone.webp?v=oct16b','"Last Name V4" Leaked':'covers/unreleased-yandhi.webp'}
for event in EVENTS:
 if event['title'] in fixes:event['cover']=fixes[event['title']]
def fix_event(match):
 try: event=json.loads(match.group())
 except ValueError:return match.group()
 if event.get('title') in fixes:
  event['cover']=fixes[event['title']];return json.dumps(event,ensure_ascii=False)
 return match.group()
text=re.sub(r'\{[^{}\n]*\}',fix_event,text)
text=text.replace('covers/unreleased-yandhi.jpg','covers/unreleased-yandhi.webp')
text=text.replace('assets/era-covers/hitler.webp','assets/era-covers/love-everyone.webp?v=oct16b')
marker='const CALENDAR_ANNUAL_EVENTS='
match=re.search(r'const\s+CALENDAR_ANNUAL_EVENTS\s*=\s*\[',text)
assert match, 'Annual calendar array missing'
missing=[e for e in EVENTS if json.dumps(e['title'],ensure_ascii=False) not in text and json.dumps(e['title']) not in text]
text=text[:match.end()]+''.join('\n'+json.dumps(e,ensure_ascii=False)+',' for e in missing)+text[match.end():]

