block='/* custom-song-covers:start */\nconst CUSTOM_SONG_COVERS='+json.dumps(song_covers)+';\n/* custom-song-covers:end */\n'
text=re.sub(r'/\* custom-song-covers:start \*/.*?/\* custom-song-covers:end \*/\n?', '', text, flags=re.S)
assert 'function localCover(x){' in text
text=text.replace('function localCover(x){',block+'function localCover(x){',1)
hook="if(x.kind==='song'){const custom=CUSTOM_SONG_COVERS[(x.spotify||'').split('/').pop()];if(custom)return custom;}"
if hook not in text:text=text.replace('function localCover(x){','function localCover(x){'+hook,1)

p.write_text(text)
p=Path('data/hosted-audio.json');data=json.loads(p.read_text());count=0
for record in data['files'].values():
 if str(record.get('era','')).strip().upper()=='SWISH':
  record['cover']='assets/era-covers/swish.webp?v=oct16';count+=1
for record in data['files'].values():
 era=str(record.get('era','')).lower()
 if 'love everyone' in era or era=='hitler' or 'hitler.webp' in record.get('cover',''):
  record['cover']='assets/era-covers/love-everyone.webp?v=oct16b'
assert count==29, f'Unexpected SWISH entry count: {count}'
